    "subject": "Your verification code is {{otp}} — M2C MarkDowns",
    "bodyHtml": "<!DOCTYPE html>\n<html lang=\"en\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"><title>Verify Your Email</title></head>\n<body style=\"margin:0;padding:0;background-color:#f4f4f5;font-family:'Segoe UI',Arial,sans-serif;\">\n  <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#f4f4f5;padding:40px 0;\">\n    <tr><td align=\"center\">\n      <table width=\"600\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);\">\n        <tr><td style=\"background-color:#e01a1b;padding:32px 40px;text-align:center;\">\n          <div style=\"font-size:30px;line-height:1;margin-bottom:8px;\">🔐</div>\n          <h1 style=\"margin:0;color:#ffffff;font-size:24px;font-weight:700;letter-spacing:-0.5px;\">Verify Your Email</h1>\n          <p style=\"margin:8px 0 0;color:#ffe2e2;font-size:14px;\">Confirm your address to submit your application</p>\n        </td></tr>\n        <tr><td style=\"padding:36px 40px;\">\n          <p style=\"margin:0 0 20px;color:#374151;font-size:15px;line-height:1.6;\">Hi {{name}},</p>\n          <p style=\"margin:0 0 20px;color:#374151;font-size:15px;line-height:1.6;\">Use the verification code below to confirm your email address and submit your vendor application. Enter it on the application form to continue.</p>\n<div style=\"margin:8px 0 4px;text-align:center;\"><div style=\"display:inline-block;padding:18px 34px;background:#faf5f2;border:1px solid #f0d9d4;border-radius:12px;\"><span style=\"font-family:'Courier New',monospace;font-size:34px;font-weight:800;letter-spacing:10px;color:#e01a1b;\">{{otp}}</span></div></div>\n          <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;margin:0 0 24px;\">\n            <tr><td style=\"padding:14px 18px;color:#6b7280;font-size:13px;line-height:1.6;\">This code expires in 10 minutes. If you didn't request it, you can safely ignore this email.</td></tr>\n          </table>\n        </td></tr>\n        <tr><td style=\"padding:20px 40px;border-top:1px solid #f0f0f0;text-align:center;\">\n          <p style=\"margin:0;color:#9ca3af;font-size:13px;\">This is an automated security message. Please do not reply to this email.</p>\n        </td></tr>\n      </table>\n    </td></tr>\n  </table>\n</body>\n</html>",
